import{d as u,C as t,o as c,c as m,j as a,a as o,E as r,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第四十六章","description":"从走马归田与戎马生郊，理解无尽欲求、战争与知足之足。","frontmatter":{"title":"道德经第四十六章","description":"从走马归田与戎马生郊，理解无尽欲求、战争与知足之足。","category":"guide","aliases":["道德经第四十六章","老子第四十六章","dao de jing chapter 46"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-46.md","filePath":"daoism/dao-de-jing/chapter-46.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-46.md"},y=u({...b,setup(g){const n=[{id:"horses-return-to-fields",label:"却走马以粪",showLabel:!0,sentences:[["天下有道，",{text:"却",glossary:"que"},{text:"走马",glossary:"zouma"},"以",{text:"粪",glossary:"fen"},"。"]],note:["【白话】天下有道，就把奔走之马退回，用于耕作施肥的农事。马不再以向外争逐、征战为务，而回到维持生活的田地。","【王弼注择要】「知足知止，无求于外，各修其内而已。」又说「故却走马以治田粪也」，将却马连到修内与治田。","【读法】却为退回，走马为奔走之马，粪在这里取施肥、治田义。它写治理之下资源用途的转变，不只是赞美田园景色。"]},{id:"war-horses-in-outskirts",label:"戎马生于郊",showLabel:!0,sentences:[["天下无道，",{text:"戎马",glossary:"rongma"},"生于",{text:"郊",glossary:"jiao"},"。"]],note:["【白话】天下无道，战马连在郊野也生起小马。这个景象写征战不止、军马久留在外，与归马农事的生活形成反面。","【王弼注择要】「贪欲无厌，不修其内，各求于外，故戎马生于郊也。」注把战事连到无厌的外求，不只描述一匹马的生育。","【读法】戎马即战马，郊为城外。生郊常从久战繁殖的形象理解；这里讨论欲求怎样推向征战，不据此把一切战争后果归责于普通人的欲望。"]},{id:"desire-and-calamity",label:"祸莫大于不知足",showLabel:!0,sentences:[["罪莫大于",{text:"可欲",glossary:"keyu"},"，祸莫大于不",{text:"知足",glossary:"zhizu"},"，",{text:"咎",glossary:"jiu"},"莫大于",{text:"欲得",glossary:"yude"},"。"]],note:["【白话】最大的罪过莫过于放纵贪欲，最大的祸患莫过于不知道满足，最大的过失莫过于一味贪求获得。三句将前面无厌外求的倾向说得更直接。","【校读】本站保留罪莫大于可欲；所据卷三电子录文未见这句，经文由祸莫大于不知足接起。本页对保留句自行释读，不补造对应王注。","【读法】可欲字面为可欲求之物，此处承前段贪欲无厌，取见可欲而纵求的读法；不将合理需要与所有愿望一概判罪。咎在此取过失、祸咎义。"]},{id:"enough-through-contentment",label:"知足之足",showLabel:!0,sentences:[["故",{text:"知足",glossary:"zhizu"},"之足，常足矣。"]],note:["【白话】所以，出于知道满足而获得的满足，才是可以长久的满足。它不把足够的标准无限向外推移。","【读法】所据录文此句未另见独立王注，不补造引文。前文知足知止、各修其内为本句提供读法：停止无尽逐求，才能把所得用来安顿生活。","【读法】知足之足不等于物质条件不再重要；不足以维持生活时，实际需要仍须解决。这里反省的是贪欲无厌，并不要求人接受任何不合理处境。"]}],s=[{id:"que",term:"却",sense:1},{id:"zouma",term:"走马",sense:1},{id:"fen",term:"粪",sense:1},{id:"rongma",term:"戎马",sense:1},{id:"jiao",term:"郊",sense:1},{id:"keyu",term:"可欲",sense:1},{id:"zhizu",term:"知足",sense:1},{id:"jiu",term:"咎",sense:1,context:"本章从贪欲无厌说祸咎，与占筮断辞的语境分开。"},{id:"yude",term:"欲得",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十六章",tabindex:"-1"},[o("道德经第四十六章 "),a("a",{class:"header-anchor",href:"#道德经第四十六章","aria-label":'Permalink to "道德经第四十六章"'},"​")],-1)),r(i,{title:"同是马，为何一边归田，一边生于郊野",summary:"本章先用马的去向对照天下有道、无道，再追问无尽欲求怎样招来祸咎，以知足之足收束。王弼将归田连到各修其内，将戎马连到贪欲无厌、各求于外，知足因而不只是个人心情。",points:[{label:"先读",text:"却走马以粪写退回奔走之马用于农事，与戎马生郊形成对照。"},{label:"再辨",text:"本站罪莫大于可欲一句未见于所据录文，保留并注明，古注不强配。"},{label:"后看",text:"知足之足重在欲求的分际，不把现实匮乏说成只需改变心态。"}],hint:"却取退回义，粪读 fèn，在此作动词；戎读 róng，咎读 jiù，可欲在本章连贪欲无厌来读。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:n,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"天下有道，却走马以粪。天下无道，戎马生于郊。",tone:"从马的用途看治理",guide:"由农事与征战的对照，观察向内安顿与向外争逐的差别。"},{text:"祸莫大于不知足，咎莫大于欲得。",tone:"无厌外求的后果",guide:"将祸咎连到无尽贪求，同时分清合理需要。"},{text:"故知足之足，常足矣。",tone:"让满足有可守的尺度",guide:"足够不再随比较不断后移，所得才可能成为安顿生活的条件。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:s}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么用马的去向开篇" tabindex="-1">象：为什么用马的去向开篇？ <a class="header-anchor" href="#象-为什么用马的去向开篇" aria-label="Permalink to &quot;象：为什么用马的去向开篇？&quot;">​</a></h3><p>同一种力量，可以回到田地帮助生产，也可以长期用于征战。这个具体对照让有道、无道落到资源怎样被使用，再引出外求无厌的问题。</p><h3 id="理-知足为何与天下的治乱有关" tabindex="-1">理：知足为何与天下的治乱有关？ <a class="header-anchor" href="#理-知足为何与天下的治乱有关" aria-label="Permalink to &quot;理：知足为何与天下的治乱有关？&quot;">​</a></h3><p>王弼将无道连到不修其内、各求于外。若治理不断追求向外扩张与争夺，资源便难回到日常生活；知足因而也涉及权力和资源的限度。</p><h3 id="用-今天怎样理解各修其内" tabindex="-1">用：今天怎样理解各修其内？ <a class="header-anchor" href="#用-今天怎样理解各修其内" aria-label="Permalink to &quot;用：今天怎样理解各修其内？&quot;">​</a></h3><p>可以先问现有资源是否已服务基本需要，再决定是否继续扩张。对个人和组织都一样：修内需要实际维护、分配与改善，不止于劝人心满意足。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先看资源流向哪里。</strong> 判断一项追求是否有益，可以观察时间、预算与人才是在改善基本生活，还是被无尽竞争消耗。却马归田的形象提供了一个具体问题。</p><p><strong>让足够的标准可以说清。</strong> 为一项追求明确所需和停止条件，能减少比较带来的不断加码。对尚未满足的基本需要，也应给出实际回应。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我投入最多的资源，正在安顿生活还是扩大争逐？我所说的足够，有没有一个不会随他人所得不断后移的尺度？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 009a 电子录文核对。</li><li>本站罪莫大于可欲一句未见于所据录文，保留句另标本站释读，不补造王弼注。粪按治田施肥读，不解作丢弃马匹。</li><li>知足连前段修内、外求与战马的对照释读，现代资源分配的类比另列解读层。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，009a</a>。</p>',15))])}}});export{_ as __pageData,y as default};
